@pure
fn classify(score: Int) -> Text {
    if score >= 90 {
        ret "ready";
    }
    if score >= 70 {
        ret "review";
    }
    ret "blocked";
}

fn main() -> Void {
    let scores: Int[] = [95, 72, 10];
    fx {
        loop i in 0..length(scores) {
            println(scores[i], " => ", classify(scores[i]));
        }
    }
    ret;
}
